tasks.solution:
paths = [
    ["vk", "email", "yandex"],
    ["yandex"],
    ["vk", "yandex"],
    ["email", "email", "yandex"],
    ["vk", "vk", "email"],
]

last_click = {}
linear = {}
for path in paths:
    last = path[-1]
    last_click[last] = last_click.get(last, 0) + 1
    for ch in path:
        linear[ch] = linear.get(ch, 0) + 1 / len(path)

result = pd.DataFrame({"last_click": pd.Series(last_click), "linear": pd.Series(linear)}).fillna(0).round(2).sort_index()
